CREATE TABLE IF NOT EXISTS acp_task_titles(task_id TEXT PRIMARY KEY REFERENCES managed_tasks(id) ON DELETE CASCADE,state TEXT NOT NULL CHECK(state IN ('pending','claimed','done')),token TEXT);
CREATE TRIGGER IF NOT EXISTS acp_task_titles_register AFTER INSERT ON managed_tasks WHEN NEW.title='' AND NEW.session_id IS NULL AND NEW.provider IN ('codex','claude') BEGIN INSERT OR IGNORE INTO acp_task_titles(task_id,state) VALUES(NEW.id,'pending'); END;
CREATE TRIGGER IF NOT EXISTS acp_task_titles_invalidate AFTER UPDATE OF title,archived ON managed_tasks WHEN OLD.title IS NOT NEW.title OR NEW.archived<>0 BEGIN UPDATE acp_task_titles SET state='done',token=NULL WHERE task_id=NEW.id; END;
